def login_page():
    """Role-specific login gate."""
    login_role = st.session_state.get("login_role")
    role_label = {"student":"Student", "admin":"Admin / Institution", "employer":"Employer"}.get(login_role, "SkillSync")

    st.markdown(f'<div class="main-title">🔐 Login as {role_label}</div>', unsafe_allow_html=True)
    st.markdown('<div class="subtitle">Enter your registered credentials to continue.</div>', unsafe_allow_html=True)

    username = st.text_input("Username / Email", placeholder="Enter your username or email", key="role_login_username")
    password = st.text_input("Password", type="password", placeholder="Enter your password", key="role_login_password")

    if st.button("Login →", use_container_width=True, type="primary", key="role_login_submit"):
        if not username.strip() or not password:
            st.error("Please enter username/email and password.")
        else:
            st.session_state.logged_in = True
            st.session_state.user_name = username.strip()
            if login_role:
                st.session_state.role = login_role
                target = {"student":"student_dashboard", "admin":"institution_dashboard", "employer":"employer_dashboard"}[login_role]
                st.session_state.login_role = None
                go_to(target)
            else:
                go_to("role_selection")

    st.markdown('<div class="signup-area standalone-signup"><span class="signup-area-text">Don\'t have an account?</span></div>', unsafe_allow_html=True)
    if st.button("Sign up", key="login_signup_btn", use_container_width=True):
        st.session_state.signup_role = login_role
        go_to("signup")

    if st.button("← Back to Home", use_container_width=True, key="login_back_home"):
        st.session_state.login_role = None
        go_to("home")


