def signup_page():
    st.markdown('<div class="main-title">✨ Create Account</div>', unsafe_allow_html=True)
    st.markdown('<div class="subtitle">Create your SkillSync account</div>', unsafe_allow_html=True)
    full_name = st.text_input("Full Name", key="signup_full_name")
    email = st.text_input("Email", key="signup_email")
    mobile = st.text_input("Mobile Number", key="signup_mobile")
    username = st.text_input("Username", key="signup_username")
    password = st.text_input("Password", type="password", key="signup_password")
    confirm_password = st.text_input("Confirm Password", type="password", key="signup_confirm")
    default_role = st.session_state.get("signup_role") or "student"
    role = st.selectbox("Account Type", ["student", "admin", "employer"], index=["student","admin","employer"].index(default_role), format_func=lambda x: {"student":"🎓 Student","admin":"🏫 Admin / Institution","employer":"💼 Employer"}[x], key="signup_role_select")
    if st.button("Create Account", use_container_width=True, type="primary", key="create_account_btn"):
        if not all([full_name.strip(), email.strip(), mobile.strip(), username.strip(), password, confirm_password]):
            st.error("Please fill in all fields.")
        elif password != confirm_password:
            st.error("Passwords do not match.")
        elif not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email.strip()):
            st.error("Please enter a valid email address.")
        elif not re.match(r"^\+?[0-9]{10,15}$", mobile.strip().replace(" ", "")):
            st.error("Please enter a valid mobile number.")
        else:
            st.session_state.logged_in = True
            st.session_state.user_name = full_name.strip()
            st.session_state.role = role
            st.session_state.signup_role = None
            go_to({"student":"student_dashboard", "admin":"institution_dashboard", "employer":"employer_dashboard"}[role])
    if st.button("Already have an account? Login", use_container_width=True, key="signup_login_btn"):
        st.session_state.login_role = role
        go_to("login")
    if st.button("← Back to Home", use_container_width=True, key="signup_back_home"):
        st.session_state.signup_role = None
        go_to("home")


