    st.markdown('<div class="subtitle">Select how you want to use SkillSync</div>', unsafe_allow_html=True)
    c1,c2,c3=st.columns(3)
    cards=[(c1,"🎓","Student","Analyze your curriculum and identify industry skill gaps.","student","student_dashboard"),(c2,"🏫","Institution Admin","Analyze academic programs and industry alignment.","admin","institution_dashboard"),(c3,"💼","Employer","Define required skills and assess workforce readiness.","employer","employer_dashboard")]
    for col,icon,title,desc,role,target in cards:
        with col:
            st.markdown(f'<div class="card"><div style="font-size:40px;">{icon}</div><div class="card-title">{title}</div><div class="card-text">{desc}</div></div>', unsafe_allow_html=True)
