def curriculum_upload_page():

    st.markdown(
        '<div class="main-title">📚 Curriculum Upload</div>', unsafe_allow_html=True
    )

    st.markdown(
        """
        <div class="subtitle">
            Upload a curriculum PDF and let SkillSync identify
            the skills inside it.
        </div>
        """,
        unsafe_allow_html=True,
    )

    if st.button("← Back to Dashboard"):
        go_to("student_dashboard")

    st.markdown(
        '<div class="section-title">Program Information</div>', unsafe_allow_html=True
    )

    program_name = st.text_input("Program Name", placeholder="B.Tech Computer Science")

    university = st.text_input("University", placeholder="ABC University")

    st.markdown(
        """
        <div class="upload-box">
            <div style="font-size:42px;">📄</div>
            <b>Upload Curriculum PDF</b>
            <br>
            <span style="color:#667085;">
                SkillSync will extract the curriculum and analyze
                the skills automatically.
            </span>
        </div>
        """,
        unsafe_allow_html=True,
    )

    uploaded_file = st.file_uploader(
        "Choose Curriculum PDF", type=["pdf"], label_visibility="collapsed"
    )

    if uploaded_file:

        file_size = uploaded_file.size / 1024

        st.markdown(
            f"""
            <div class="success-card">
                <b>✓ PDF Uploaded Successfully</b><br>
                File: {uploaded_file.name}<br>
                Size: {file_size:.2f} KB
            </div>
            """,
            unsafe_allow_html=True,
        )

        if st.button("🔍 Analyze Curriculum", use_container_width=True):

            if not program_name:

                st.warning("Please enter the program name.")

            elif extract_text_from_pdf is None:

                st.error(
                    "pdf_processor.py could not be found. "
                    "Please make sure your existing pdf_processor.py "
                    "file is present in the SkillSync project folder."
                )

            else:

                with st.spinner("Extracting curriculum from PDF..."):

                    try:

                        extracted_text = extract_text_from_pdf(uploaded_file)

                    except Exception as e:

                        st.error(f"Unable to read the PDF: {e}")
                        return

                if not extracted_text or not extracted_text.strip():

                    st.error("No readable text was found in this PDF.")

                else:

                    with st.spinner("Analyzing skills..."):

                        detected_skills = extract_skills(extracted_text)

                    st.success("Curriculum analysis completed!")

                    st.markdown(
                        '<div class="section-title">🧠 Detected Skills</div>',
                        unsafe_allow_html=True,
                    )

                    if detected_skills:

                        cols = st.columns(4)

                        for index, skill in enumerate(detected_skills):

                            with cols[index % 4]:

                                st.markdown(
                                    f"""
                                    <div class="skill-card">
                                        <div class="skill-name">
                                            ✓ {skill}
                                        </div>
                                    </div>
                                    """,
                                    unsafe_allow_html=True,
                                )

                    else:

                        st.info("No predefined skills were detected.")

                    # Industry comparison

                    matched = [
                        skill for skill in detected_skills if skill in INDUSTRY_SKILLS
                    ]

                    missing = [
                        skill
                        for skill in INDUSTRY_SKILLS
                        if skill not in detected_skills
                    ]

                    if INDUSTRY_SKILLS:

                        match_percentage = int(
                            len(matched) / len(INDUSTRY_SKILLS) * 100
                        )

                    else:

                        match_percentage = 0

                    st.markdown(
                        '<div class="section-title">🏭 Industry Alignment</div>',
                        unsafe_allow_html=True,
                    )

                    c1, c2, c3 = st.columns(3)

                    with c1:
                        st.metric("Industry Match", f"{match_percentage}%")

                    with c2:
                        st.metric("Matched Skills", len(matched))

                    with c3:
                        st.metric("Skill Gaps", len(missing))

                    st.progress(match_percentage / 100)

                    st.markdown(
                        '<div class="section-title">⚠️ Industry Skill Gaps</div>',
                        unsafe_allow_html=True,
                    )

                    for skill in missing:

                        st.markdown(
                            f"""
                            <div class="gap-card">
                                <b>{skill}</b><br>
                                <span style="color:#667085;">
                                    This industry skill was not detected
                                    in the uploaded curriculum.
                                </span>
                            </div>
                            """,
                            unsafe_allow_html=True,
                        )

                    st.markdown(
                        '<div class="section-title">💡 Recommendations</div>',
                        unsafe_allow_html=True,
                    )

                    if missing:

                        st.markdown(
                            """
                            <div class="recommendation">
                                <div class="recommendation-title">
                                    Improve Industry Readiness
                                </div>

                                <div class="recommendation-text">
                                    Consider adding practical modules,
                                    projects and certifications covering
                                    the missing industry skills.
                                </div>
                            </div>
                            """,
                            unsafe_allow_html=True,
                        )

                    else:

                        st.markdown(
                            """
                            <div class="success-card">
                                <b>Excellent Alignment!</b><br>
                                The curriculum covers the major
                                industry skills in the SkillSync database.
                            </div>
                            """,
                            unsafe_allow_html=True,
                        )


